order = []
results = []
accepted = 0
replayed = 0
rejected = 0

for idx, ev in enumerate(cfg["events"]):
    t = ev["t"]
    while order and order[0][0] + ttl <= t:
        old = order.pop(0)[1]
        ledger.pop(old, None)

    peer_id = ev["peer"]
    mode, allowed = peers[peer_id]
    auth = ev["auth"]
    egress = ev["egress"]
    wh = ev["wire_hex"]

    res = None
    req = None
    reason = None
    if len(wh) & 1 or not HEXDIG.issuperset(wh):
        reason = "hex"
    else:
        try:
            req = parse_request(bytes.fromhex(wh))
        except SyntaxError_:
            reason = "syntax"
        except _Headers:
            reason = "headers"
        except _Length:
            reason = "length"
        except FieldError:
            reason = "fields"

    if reason is None:
        privacy = req["privacy"]
        ppi = req["ppi"]
        pai = req["pai"]
        from_canon = req["from"]
        if mode == "access":
            if auth is None:
                reason = "auth"
            else:
                acc = auth
                aset = account_aliases[acc]
                if ppi is not None:
                    ok = True
                    for u in ppi:
                        if u not in aset:
                            ok = False
                            break
                    if not ok:
                        reason = "identity"
                    else:
                        asserted = ppi
                else:
                    asserted = [account_default[acc]]
        else:
            if ppi is not None or pai is None:
                reason = "identity"
            else:
                owner = None
                ok = True
                for u in pai:
                    o = alias_owner.get(u)
                    if o is None:
                        ok = False
                        break
                    if owner is None:
                        owner = o
                    elif owner != o:
                        ok = False
                        break
                if not ok:
                    reason = "identity"
                elif owner not in allowed:
                    reason = "identity"
                else:
                    acc = owner
                    asserted = pai
        if reason is None:
            if from_canon in account_aliases[acc]:
                pass
            elif from_canon == ANON and privacy == "id":
                pass
            else:
                reason = "identity"

    if reason is not None:
        rejected += 1
        results.append({"index": idx, "decision": "reject",
                        "reason": reason})
        continue

    selected = asserted[0]
    privacy = req["privacy"]
    if req["privacy"] == "id":
        from_out = ANON
    else:
        from_out = selected
